using Medzo.CatalogueInventory.Domain.Common;
namespace Medzo.CatalogueInventory.Domain.Messaging;
public sealed class OutboxMessage:Entity{private OutboxMessage(){}public OutboxMessage(string topic,string key,string type,string payload){Topic=topic;Key=key;Type=type;Payload=payload;OccurredAtUtc=DateTime.UtcNow;}public string Topic{get;private set;}=null!;public string Key{get;private set;}=null!;public string Type{get;private set;}=null!;public string Payload{get;private set;}=null!;public DateTime OccurredAtUtc{get;private set;}public DateTime? ProcessedAtUtc{get;private set;}public int Attempts{get;private set;}public string? LastError{get;private set;}public void MarkProcessed()=>ProcessedAtUtc=DateTime.UtcNow;public void MarkFailed(string error){Attempts++;LastError=error[..Math.Min(error.Length,1000)];}}
